<script lang="ts">
  import { AREAS, indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Modal } from '../../shared/data.js';
  type Node = { id:string; label:string; kind:string; keys:string[]; children:Node[]; parent?:Node; counts:Record<string,number> };
  type Arc = { node:Node; start:number; end:number; depth:number };
  const modes:Modal[] = ['should','may','can','must','fact'];
  const fills:Record<string,string> = { should:'var(--action)', may:'var(--graph-entity)', can:'var(--graph-entity)', must:'var(--graph-event)', fact:'var(--graph-document)' };
  let g = $state.raw<Guideline|null>(null);
  let state = $state.raw<HashState>(readHash());
  let focused = $state('root');
  let query = $state('');
  let failure = $state('');
  const ix = $derived(g ? indexGuideline(g) : null);
  function make(id:string,label:string,kind:string,children:Node[] = [],keys:string[] = []):Node {
    const all = children.length ? children.flatMap(n=>n.keys) : keys;
    const counts:Record<string,number> = {};
    for(const key of all) {const m=ix?.sentence(key)?.modal??'fact'; counts[m]=(counts[m]??0)+1;}
    const n:Node={id,label,kind,keys:all,children,counts}; children.forEach(c=>c.parent=n); return n;
  }
  const tree = $derived.by(()=> {
    if(!g || !ix) return null;
    return make('root','CDC opioid guideline','Guideline',AREAS.map(area=>make(area.id,area.label,'Clinical area',area.recs.map(num=>make(`rec${num}`,`Recommendation ${num}`,'Recommendation',g!.documents.filter(d=>d.rec===num).map(d=>make(d.id,d.id.replace('cdc2022-opioid-',''),d.kind,d.sentences.map(s=>make(`${d.id}:${s.n}`,`Sentence ${s.n}`,'Sentence',[],[`${d.id}:${s.n}`])))))))));
  });
  const nodes = $derived.by(()=> {const map=new Map<string,Node>(); const visit=(n:Node)=>{map.set(n.id,n);n.children.forEach(visit);}; if(tree)visit(tree);return map;});
  const focus = $derived(nodes.get(focused)??tree);
  const question = $derived(state.view==='trace'?g?.questions.find(q=>q.id===state.question):undefined);
  const activeKeys = $derived(new Set(state.view==='trace' ? question?.statements.map(s=>`${s.document}:${s.sentence}`)??[] : state.view==='rule'?[`${state.document}:${state.sentence}`]:state.view==='explore'?g?.documents.flatMap(d=>d.sentences.filter(s=>s.ace.toLowerCase().includes(state.query.toLowerCase())).map(s=>`${d.id}:${s.n}`))??[]:[]));
  const arcs = $derived.by(()=> {
    const out:Arc[]=[];
    function visit(n:Node,start:number,end:number,depth:number){if(depth>3)return;out.push({node:n,start,end,depth});let at=start;for(const c of n.children){const next=at+(end-start)*c.keys.length/Math.max(n.keys.length,1);visit(c,at,next,depth+1);at=next;}}
    if(focus){let at=0;for(const child of focus.children){const end=at+Math.PI*2*child.keys.length/Math.max(focus.keys.length,1);visit(child,at,end,1);at=end;}}
    return out;
  });
  const crumbs = $derived.by(()=>{const a:Node[]=[];let n=focus;while(n){a.unshift(n);n=n.parent??null;}return a;});
  const ringDepth = $derived(focus?.children[0]?.kind==='Sentence'?1:focus?.children[0]?.children[0]?.kind==='Sentence'?2:3);
  function point(r:number,a:number){return `${320+r*Math.sin(a)},${320-r*Math.cos(a)}`;}
  function path(a:Arc){const band=190/ringDepth;const r0=99+(a.depth-1)*band,r1=r0+band-3;const end=Math.min(a.end,a.start+Math.PI*2-.0001);const large=end-a.start>Math.PI?1:0;return `M${point(r0,a.start)} L${point(r1,a.start)} A${r1},${r1} 0 ${large} 1 ${point(r1,end)} L${point(r0,end)} A${r0},${r0} 0 ${large} 0 ${point(r0,a.start)} Z`;}
  function dominant(n:Node){return modes.reduce((a,b)=>(n.counts[b]??0)>(n.counts[a]??0)?b:a,'fact');}
  function navigate(s:HashState){state=s;writeHash(s);sync();}
  function sync(){query=state.view==='explore'?state.query:'';focused=state.view==='rule'?state.document:'root';}
  function select(n:Node){if(n.kind==='Sentence'){const at=n.id.lastIndexOf(':');navigate({view:'rule',document:n.id.slice(0,at),sentence:Number(n.id.slice(at+1))});}else focused=n.id;}
  $effect(()=>{const update=()=>{state=readHash();sync();};addEventListener('hashchange',update);sync();void loadGuideline().then(data=>g=data).catch(e=>failure=String(e));return()=>removeEventListener('hashchange',update);});
  $effect(()=>{void state;void focus;if(g)queueMicrotask(markReady);});
  const selectedDoc = $derived(state.view==='rule'?ix?.docs.get(state.document):undefined);
  const selectedSentence = $derived(state.view==='rule'?ix?.sentence(`${state.document}:${state.sentence}`):undefined);
  const selectedRule = $derived(state.view==='rule'?ix?.rules.get(`${state.document}:${state.sentence}`):undefined);
</script>

<main>
<header><div><p class="brand">CNL / CKC <span>Guideline atlas</span></p><h1>Guideline rings</h1></div><nav aria-label="Graph views"><button onclick={()=>navigate({view:'overview'})}>Whole guideline</button><select aria-label="Trace an answer" value={question?.id??''} onchange={e=>{if(e.currentTarget.value)navigate({view:'trace',question:e.currentTarget.value});}}><option value="">Trace an answer…</option>{#each g?.questions??[] as q}<option value={q.id}>{q.question}</option>{/each}</select></nav></header>
<form onsubmit={e=>{e.preventDefault();navigate({view:'explore',query});}}><label for="search">Find a phrase in the knowledge base</label><div class="search"><input id="search" bind:value={query} placeholder="For example, naloxone"/><button>Find sentences</button></div></form>
{#if failure}<p role="alert">{failure}</p>{:else if !g||!focus}<p>Loading the guideline…</p>{:else}
<p class="legend">Rings contain areas, recommendations, documents, then sentences. Arc length counts sentences; colour shows the dominant modal.</p>
<div class="modal-legend">{#each modes as mode}<span><i style:background={fills[mode]}></i>{mode}</span>{/each}<span class="trace-key">Outline = selected answer or search match</span></div>
<div class="workspace"><section class="radial" aria-label="Zoomable guideline hierarchy"><div class="breadcrumbs">{#each crumbs as c}<button onclick={()=>focused=c.id}>{c.kind==='Guideline'?'Guideline':c.label}</button>{/each}</div>
<svg viewBox="0 0 640 640" aria-label="Guideline sunburst"><title>Guideline containment hierarchy</title>{#each arcs as arc}<a href="#overview" onclick={e=>{e.preventDefault();select(arc.node);}} aria-label={`${arc.node.label}, ${arc.node.keys.length} sentences. Open ${arc.node.kind}.`}><path d={path(arc)} fill={fills[dominant(arc.node)]} class:matched={arc.node.keys.some(k=>activeKeys.has(k))} class:dimmed={activeKeys.size>0&&!arc.node.keys.some(k=>activeKeys.has(k))}><title>{arc.node.label}: {arc.node.keys.length} sentences</title></path></a>{#if arc.depth===1&&arc.end-arc.start>.15}{@const mid=(arc.start+arc.end)/2}<text x={320+(99+95/ringDepth)*Math.sin(mid)} y={320-(99+95/ringDepth)*Math.cos(mid)} text-anchor="middle" dominant-baseline="middle">{arc.node.kind==='Clinical area'?AREAS.findIndex(a=>a.id===arc.node.id)+1:arc.node.label.replace('Recommendation ','R').replace('Sentence ','S')}</text>{/if}{/each}<circle cx="320" cy="320" r="93" fill="var(--surface-raised)"/><foreignObject x="246" y="257" width="148" height="80"><div class="centre-label">{focus.label}</div></foreignObject><text x="320" y="365" class="count" text-anchor="middle">{focus.keys.length}</text><text x="320" y="390" class="centre" text-anchor="middle">sentences</text></svg>
<p class="hint">Select an arc to open its contents. Use the breadcrumb to return.</p>
<details><summary>Hierarchy as a list</summary>{#each focus.children as child}<button class="list-item" onclick={()=>select(child)}>{child.label} <span>{child.keys.length} sentences</span></button>{/each}</details></section>
<aside>
{#if state.view==='trace'}<h2>Trace an answer</h2>{#if question}<h3>{question.question}</h3><p class="notice">{g.derivation}</p><ol class="statements">{#each question.statements as s}<li><a href={`#rule=${s.document}:${s.sentence}`}>{ix?.sentence(`${s.document}:${s.sentence}`)?.ace}</a><p>{s.document}, sentence {s.sentence} <a href={`${g.pdf}#page=${ix?.docs.get(s.document)?.page}`} target="_blank" rel="noreferrer">Page {ix?.docs.get(s.document)?.page}</a></p><details><summary>Source text</summary><p>{ix?.docs.get(s.document)?.source}</p></details></li>{/each}</ol>{:else}<p>Question not found. Select a question above.</p>{/if}
{:else if state.view==='rule'}<h2>Read one rule</h2>{#if selectedSentence&&selectedDoc}<p class="locator">{selectedDoc.id}, sentence {selectedSentence.n}</p><blockquote>{selectedSentence.ace}</blockquote>{#if selectedRule}<h3>Clinical rule structure</h3><p><b>Condition</b><br/>{selectedRule.condition??'No explicit condition in this rule.'}</p><p><b>Actor</b><br/>{selectedRule.subject}</p><p><b>Modal</b> {selectedRule.mode}</p>{#each selectedRule.actions as a}<p class="logic"><b>{a.polarity==='negative'?'NOT ':''}{a.verb}</b> {a.object}{#each a.modifiers as m}{' '}{m.preposition} {m.value}{/each}</p>{/each}{:else}<h3>Text reading (prototype heuristic)</h3><p><b>Condition:</b> {selectedSentence.condition??'None stated'}</p><p><b>Conclusion:</b> {selectedSentence.conclusion}</p><p><b>Modal:</b> {selectedSentence.modal}; negated: {selectedSentence.negated?'yes':'no'}</p>{/if}<details open><summary>Guideline source</summary><p>{selectedDoc.source}</p><a href={`${g.pdf}#page=${selectedDoc.page}`} target="_blank" rel="noreferrer">Open page {selectedDoc.page}</a></details>{:else}<p>Sentence not found. Search for another sentence above.</p>{/if}
{:else if state.view==='explore'}<h2>Sentences containing “{state.query}”</h2><p>{activeKeys.size} matches. Matching arcs are outlined.</p>{#each [...activeKeys] as key}<a class="result" href={`#rule=${key}`}><span>{key}</span>{ix?.sentence(key)?.ace}</a>{/each}{#if activeKeys.size===0}<p>No sentences found. Try another phrase.</p>{/if}
{:else}<h2>{focus.label}</h2>{#if ix?.docs.get(focus.id)}{@const d=ix.docs.get(focus.id)!}<p>{d.source}</p><a href={`${g.pdf}#page=${d.page}`} target="_blank" rel="noreferrer">Open page {d.page}</a>{/if}<p>The inner ring gives the clinical areas. The outer rings show where the guideline spends its words, not the strength of its evidence.</p><p class="notice">{g.derivation}</p><h3>Modal mix in this selection</h3><div class="mix">{#each modes as mode}<span>{mode} <b>{focus.counts[mode]??0}</b></span>{/each}</div>{#each focus.children as child}<button class="list-item" onclick={()=>select(child)}>{child.label}<span>{child.keys.length} sentences</span></button>{/each}
{/if}
</aside></div>
<section class="records"><details><summary>Scope exclusions ({g.exclusions.length} source records)</summary><p>The recommendations do not apply under these conditions. Their absence does not establish that a patient belongs to the guideline population.</p>{#each g.exclusions as e}<p><a href={`#rule=${e.document}:${e.sentence}`}>{e.ace}</a><br/><small>{e.document}, sentence {e.sentence}</small></p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as s}<p><s>{s.ace}</s><br/>Superseded {String(s.date).slice(0,4)}-{String(s.date).slice(4,6)}-{String(s.date).slice(6)} <a href={s.url}>{s.citation}</a><br/><a href={`#rule=${s.document}:${s.sentence}`}>Read source sentence</a></p>{/each}</details><details><summary>Guideline-wide documents outside the four areas</summary>{#each g.documents.filter(d=>d.rec===null) as d}<p><a href={`#rule=${d.id}:${d.sentences[0]?.n}`}>{d.id}</a> ({d.sentences.length} sentences)</p>{/each}</details></section>
<footer>CDC Clinical Practice Guideline for Prescribing Opioids for Pain, 2022. Free at <a href="https://www.cdc.gov/mmwr/volumes/71/rr/rr7103a1.htm">cdc.gov</a>. CDC does not endorse this demonstration. Prototype, not clinical advice.</footer>
{/if}
</main>

<style>
main{max-width:1440px;margin:auto;padding:28px 38px}header{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:22px}.brand{font-weight:700;margin:0}.brand span{font-weight:400;color:var(--text-muted);margin-left:18px}h1{font-size:34px;line-height:1.2;margin:8px 0 0;letter-spacing:-.6px}nav{display:flex;gap:10px;flex-wrap:wrap}button,select,input{color:var(--text);background:var(--surface-raised);border:1px solid var(--border);border-radius:3px;padding:8px 12px;max-width:100%}button,select{cursor:pointer}button:hover{background:var(--surface-sunken)}:is(button,a,input,select,summary):focus-visible{outline:3px solid var(--focus-ring);outline-offset:3px}a{color:var(--action);text-underline-offset:3px}form{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--border);padding-bottom:18px}.search{display:flex;gap:8px}input{width:260px;min-width:0}.legend{margin:18px 0 9px;max-width:90ch;color:var(--text-muted)}.modal-legend{display:flex;gap:17px;flex-wrap:wrap;font-size:13px}.modal-legend span{display:flex;gap:6px;align-items:center}i{width:12px;height:12px;display:inline-block}.trace-key{margin-left:auto}.workspace{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:34px;margin-top:24px}.radial{min-width:0}.breadcrumbs{display:flex;flex-wrap:wrap;gap:5px;min-height:35px}.breadcrumbs button{padding:3px 8px;font-size:13px}.radial svg{width:100%;display:block;max-height:540px}path{stroke:var(--surface);stroke-width:.65}path.matched{stroke:var(--graph-path);stroke-width:3;filter:brightness(1.1)}path.dimmed{opacity:.18}svg a:focus path{stroke:var(--focus-ring);stroke-width:4}svg text{pointer-events:none;fill:var(--action-text);font-size:12px;font-weight:700}.centre-label{color:var(--text);font-size:14px;line-height:1.2;text-align:center;height:80px;display:flex;align-items:center;justify-content:center;overflow-wrap:anywhere}.centre{fill:var(--text-muted);font-size:14px;font-weight:400}.count{fill:var(--text);font-size:39px}.hint{font-size:13px;color:var(--text-muted);text-align:center;margin-top:0}aside{border-left:1px solid var(--border);padding-left:28px;min-width:0;max-height:700px;overflow:auto;padding-right:12px}h2{font-size:24px;line-height:1.25;margin:0 0 18px}h3{font-size:18px;line-height:1.4}.notice{font-size:13px;color:var(--text-muted);border-left:3px solid var(--border);padding-left:12px}.list-item{display:flex;justify-content:space-between;gap:15px;text-align:left;width:100%;border-width:0 0 1px;border-radius:0;padding:11px 0;background:transparent}.list-item span{font-size:12px;color:var(--text-muted);flex-shrink:0}.mix{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}.mix span{font-size:13px}.mix b{display:block;font-size:22px}.locator,small{font-size:13px;overflow-wrap:anywhere;color:var(--text-muted)}blockquote{font-size:19px;line-height:1.5;border-left:4px solid var(--action);padding-left:18px;margin:15px 0 24px}.logic{border-left:3px solid var(--graph-entity);padding:8px 14px;background:var(--surface-sunken)}.result{display:block;padding:14px 0;border-bottom:1px solid var(--border);text-decoration:none}.result span{display:block;font-size:12px;color:var(--text-muted);overflow-wrap:anywhere}.statements{padding-left:21px}.statements li{padding:0 0 22px 8px}.statements li>p{font-size:12px;overflow-wrap:anywhere}.records{border-top:1px solid var(--border);margin-top:30px;padding-top:12px;display:grid;gap:12px}.records p{max-width:85ch}summary{cursor:pointer;font-weight:600}footer{font-size:12px;color:var(--text-muted);margin-top:25px;max-width:100ch}p{overflow-wrap:anywhere}@media(max-width:760px){svg text{font-size:24px}.centre-label{font-size:24px}.centre{font-size:24px}.count{font-size:48px}main{padding:19px 17px}header,form{display:block}h1{font-size:28px}nav{margin-top:19px}select{width:100%}form{margin-top:20px}.search{margin-top:8px}input{width:100%;flex:1}.search button{padding:7px;white-space:nowrap}.workspace{display:block;margin-top:18px}.trace-key{margin-left:0}.modal-legend{gap:10px}.legend{font-size:13px}aside{border-left:0;border-top:1px solid var(--border);padding:23px 0 0;max-height:none;margin-top:18px}.radial svg{margin:0 -5px;width:calc(100% + 10px)}.brand span{margin-left:9px}.list-item span{white-space:normal;flex-shrink:1}h2{font-size:22px}.records{margin-top:24px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
